(()=>{
'use strict';
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',box:'<path d="m3 7 9-4 9 4v10l-9 4-9-4zM3 7l9 4 9-4M12 11v10M8 5l9 4"/>',shield:'<path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6z"/><path d="m8 12 3 3 5-6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',chart:'<path d="M4 3v17h17M8 15v-4M13 15V7M18 15v-7"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',arrow:'<path d="m9 5 7 7-7 7"/>',back:'<path d="m12 5-7 7 7 7M5 12h15"/>',check:'<path d="m5 12 4 4L19 6"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',truck:'<path d="M3 5h11v11H3zM14 9h4l3 4v3h-7"/><circle cx="7" cy="18" r="2"/><circle cx="17" cy="18" r="2"/>',chat:'<path d="M21 11a8 8 0 0 1-8 8H6l-4 3 1-7a8 8 0 0 1 10-11 8 8 0 0 1 8 7z"/><path d="M7 11h.01M12 11h.01M17 11h.01"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3M12 17h.01"/>',refresh:'<path d="M20 7a9 9 0 1 0 1 8M20 3v5h-5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0z"/><circle cx="12" cy="10" r="2"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 8h18M16 12h5v5h-5z"/>',bell:'<path d="M6 9a6 6 0 0 1 12 0v7l2 2H4l2-2zM10 21h4"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>'};
const icon=n=>`<svg aria-hidden="true" viewBox="0 0 24 24">${icons[n]||icons.box}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'฿'+Number(n).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
function seeds(){return [
{id:'SPX2609250142',buyer:'Emma Wilson',item:'Everyday insulated tumbler',shop:'Daily Essentials',value:599,risk:'High',score:18,status:'Ready for dispatch',readiness:'Not contacted',payment:'COD',slot:'26 Sep · 12:00–15:00',address:'42 Riverside Residence, Khlong San, Bangkok 10600',phone:'+66 81 234 0182',factors:['Order has waited 5 days before last-mile dispatch','Two verified COD refusals in the previous 90 days','Area has elevated final delivery failures'],attempts:0,group:'AI',reliability:'Sufficient history'},
{id:'SPX2609250186',buyer:'Alex Morgan',item:'Wireless desk charger',shop:'Tech Everyday',value:890,risk:'Medium',score:7,status:'Ready for dispatch',readiness:'Not contacted',payment:'COD',slot:'26 Sep · 09:00–12:00',address:'18 Park Offices, Phaya Thai, Bangkok 10400',phone:'+66 82 456 0193',factors:['Previous weekday attempt missed','Office address has restricted access after 18:00'],attempts:0,group:'Rules',reliability:'Sufficient history'},
{id:'SPX2609250217',buyer:'Jamie Lee',item:'Cotton everyday tote',shop:'Studio Basics',value:249,risk:'Low',score:1,status:'Out for delivery',readiness:'Standard delivery',payment:'COD',slot:'25 Sep · 12:00–15:00',address:'71 Green Court, Bang Rak, Bangkok 10500',phone:'+66 83 456 0120',factors:['12 recent successful deliveries','Complete and previously verified address'],attempts:0,group:'Control',reliability:'Sufficient history'},
{id:'SPX2609250238',buyer:'Sam Taylor',item:'Portable reading lamp',shop:'Home Edit',value:459,risk:'Medium',score:9,status:'Attempt unsuccessful',readiness:'Unavailable',payment:'COD',slot:'25 Sep · 09:00–12:00',address:'29 Central Loft, Din Daeng, Bangkok 10400',phone:'+66 84 567 0183',factors:['First attempt recorded as buyer unavailable','Buyer has 8 successful prior deliveries'],attempts:1,reason:'Buyer unavailable',group:'AI',reliability:'Sufficient history'},
{id:'SPX2609250251',buyer:'Robin Chen',item:'Travel organizer set',shop:'Pack & Go',value:379,risk:'High',score:21,status:'Return in progress',readiness:'Cancellation requested',payment:'Prepaid',slot:'25 Sep · 12:00–15:00',address:'56 River View, Bangkok Noi, Bangkok 10700',phone:'+66 85 678 0109',factors:['Buyer confirmed that the item is no longer wanted','Return authorized after verified cancellation request'],attempts:1,group:'Rules',refund:'Refund processing',returnDate:'28 Sep 2026',reliability:'Sufficient history'},
{id:'SPX2609250264',buyer:'Casey Brown',item:'Ceramic coffee cup',shop:'Slow Morning',value:329,risk:'Low',score:2,status:'Delivered',readiness:'Confirmed ready',payment:'COD collected',slot:'25 Sep · 09:00–12:00',address:'12 Orchard Lane, Sathorn, Bangkok 10120',phone:'+66 86 789 0114',factors:['Stable delivery history','Address verified'],attempts:1,group:'Control',reliability:'Sufficient history'},
{id:'SPX2609250289',buyer:'Drew Parker',item:'Foldable laptop stand',shop:'Workwell',value:699,risk:'High',score:16,status:'Under review',readiness:'Disputed attempt',payment:'COD',slot:'25 Sep · 12:00–15:00',address:'88 Lake Residence, Huai Khwang, Bangkok 10310',phone:'+66 87 890 0118',factors:['Reported delivery attempt is disputed','Attempt evidence needs human verification'],attempts:1,group:'AI',reliability:'Evidence under review'},
{id:'SPX2609250295',buyer:'Taylor James',item:'Minimal notebook set',shop:'Paper Practice',value:189,risk:'Unscored',score:null,status:'Ready for dispatch',readiness:'Standard delivery',payment:'COD',slot:'26 Sep · 12:00–15:00',address:'24 East Court, Bang Kapi, Bangkok 10240',phone:'+66 88 901 0142',factors:['New account with insufficient delivery history','Use the standard service fallback'],attempts:0,group:'Control',reliability:'Limited history'}
].map(o=>({...o,contactCount:0,events:[{time:'25 Sep · 10:42',text:o.status==='Delivered'?'Parcel delivered; COD collection confirmed':o.status==='Return in progress'?'Return authorized; prepaid refund processing':o.status==='Attempt unsuccessful'?'Delivery attempt unsuccessful: buyer unavailable':o.status==='Under review'?'Buyer disputed the attempt; human review opened':'Parcel arrived at Bang Na destination hub',actor:'SPX Operations'},{time:'24 Sep · 21:15',text:'Parcel processed at sorting center',actor:'SPX Network'},{time:'23 Sep · 16:20',text:'Seller handed parcel to courier',actor:'Seller'}],messages:[],claim:null}));}
let orders=seeds();let state={role:'ops',view:'overview',selected:orders[0].id,buyerTab:'tracking',query:'',risk:'All',status:'All'};
const getOrder=()=>orders.find(o=>o.id===state.selected)||orders[0];
const closed=o=>['Delivered','Return in progress','Returned'].includes(o.status);
const badge=(v,type)=>`<span class="badge ${type||({High:'high',Medium:'medium',Low:'low',Delivered:'success','Confirmed ready':'success','Return in progress':'neutral','Under review':'high','Attempt unsuccessful':'medium','Out for delivery':'blue'}[v]||'neutral')}">${esc(v)}</span>`;
function addEvent(o,text,actor=state.role==='buyer'?'Buyer':'Operations'){o.events.unshift({time:'25 Sep · '+new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}),text,actor});}
function toast(t){const el=document.getElementById('toast');el.textContent=t;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),4200);}
function renderAppHeader(){return `<header class="topbar"><div class="brand"><div class="brandmark">S</div>Shopee <em>Delivery Success Engine</em></div><div class="topright"><span class="demo">INTERACTIVE PROTOTYPE</span><div class="roles" aria-label="Workspace"><button data-act="role" data-value="ops" class="${state.role==='ops'?'active':''}">Operations</button><button data-act="role" data-value="buyer" class="${state.role==='buyer'?'active':''}">Buyer app</button></div><button class="btn ghost" data-act="reset">${icon('refresh')}<span class="mobilehide">Reset demo</span></button><div class="avatar">SG</div></div></header>`;}
function sidebar(){return `<aside class="sidebar"><div class="label">SPX Operations</div>${[['overview','grid','Overview'],['orders','box','Order workspace'],['recovery','refresh','Recovery queue'],['pilot','chart','Pilot insights'],['policy','shield','Service safeguards']].map(([v,i,l])=>`<button class="navbtn ${state.view===v||(state.view==='detail'&&v==='orders')?'active':''}" data-act="view" data-value="${v}">${icon(i)}${l}</button>`).join('')}<div class="sidebottom"><p class="small"><span class="pilotdot"></span>Bangkok pilot</p><p class="small" style="color:#8494a7;margin-top:8px">Bang Na destination hub<br>25 September 2026</p><p class="small" style="color:#8494a7;margin-top:15px">Synthetic orders<br>Changes stay in this tab.</p></div></aside>`;}
function heading(title,sub,actions=''){return `<div class="pagehead"><div><div class="crumb">Delivery success / ${state.view==='detail'?'Order details':'Bangkok pilot'}</div><h1>${title}</h1><p>${sub}</p></div><div class="row">${actions}</div></div>`;}
function metrics(){const needy=orders.filter(o=>!closed(o)&&o.risk!=='Low'&&o.risk!=='Unscored').length;return `<div class="metrics">${[['Eligible orders',orders.length,'Original COD cohort'],['Needs attention',needy,'Readiness or recovery'],['Ready buyers',orders.filter(o=>o.readiness==='Confirmed ready').length,'Explicit buyer confirmations'],['Delivered',orders.filter(o=>o.status==='Delivered').length,'Verified handovers']].map(([l,n,s])=>`<div class="metric"><div class="label">${l}</div><div class="num">${n.toString().padStart(2,'0')}</div><div class="small">${s}</div></div>`).join('')}</div>`;}
function rows(list){return list.map(o=>`<tr><td><button class="orderlink" data-act="open" data-id="${o.id}">${o.id.slice(-6)} ${icon('arrow')}</button><div class="small muted">${esc(o.buyer)}</div></td><td>${badge(o.risk)}<div class="small muted">${o.score===null?'Not scored':o.score+'% estimated risk'}</div></td><td>${badge(o.status)}<div class="small muted">${esc(o.readiness)}</div></td><td>${money(o.value)}<div class="small muted">${esc(o.payment)}</div></td><td><button class="link" data-act="open" data-id="${o.id}">Review ${icon('arrow')}</button></td></tr>`).join('');}
function table(list){return list.length?`<div class="tablewrap"><table><thead><tr><th>Order / buyer</th><th>Risk assessment</th><th>Delivery status</th><th>Order value</th><th>Action</th></tr></thead><tbody>${rows(list)}</tbody></table></div>`:`<div class="empty">${icon('search')}<p>No orders match these filters.</p><button class="link" data-act="clearfilters">Clear filters</button></div>`;}
function latest(){return orders.flatMap(o=>o.events.slice(0,1).map(e=>({...e,id:o.id}))).slice(0,4).map(e=>`<div class="activity"><div class="activity-icon">${icon('clock')}</div><div><p>${esc(e.text)}</p><div class="small">${e.id.slice(-6)} · ${esc(e.actor)}</div></div></div>`).join('');}
function overview(){return heading('Every delivery deserves a clear next step.','Review at-risk COD orders and help buyers receive their parcels.',`<button class="btn primary" data-act="view" data-value="orders">Open order workspace ${icon('arrow')}</button>`)+metrics()+`<div class="dashboard-grid"><div class="stack"><div class="banner">${icon('shield')}<div><h3>Support first. Keep COD available.</h3><p>Risk guides outreach. A score or unanswered message never automatically holds a parcel.</p></div></div><section class="panel"><div class="panelhead"><div><h2>Today’s priority orders</h2><p class="small muted" style="margin-top:5px">Review the evidence before choosing an action.</p></div>${badge('Live demo','blue')}</div>${table(orders.filter(o=>!closed(o)&&o.risk!=='Low'&&o.risk!=='Unscored'))}</section><section class="panel"><div class="panelhead"><h2>One workflow, both sides</h2></div><div class="panelbody"><div class="steps"><div class="step active"><strong>01 / Assess</strong>Identify delivery risk</div><div class="step"><strong>02 / Ask</strong>Check buyer readiness</div><div class="step"><strong>03 / Support</strong>Match feasible options</div><div class="step"><strong>04 / Recover</strong>Resolve missed attempts</div></div><button class="link" data-act="role" data-value="buyer">Open the buyer experience ${icon('arrow')}</button></div></section></div><div class="stack"><section class="panel"><div class="panelhead"><h2>Risk distribution</h2></div><div class="panelbody"><p class="small muted">Illustrative scores, not a trained model</p><div class="riskbar">${[['High','#ed7a65'],['Medium','#eec46a'],['Low','#69b7a4'],['Unscored','#c5cbd2']].map(([r,c])=>`<i style="width:${orders.filter(o=>o.risk===r).length/orders.length*100}%;background:${c}"></i>`).join('')}</div>${[['High','#ed7a65'],['Medium','#eec46a'],['Low','#69b7a4'],['Unscored','#c5cbd2']].map(([r,c])=>`<div class="ministat"><span><i class="dot" style="background:${c}"></i>${r}</span><strong>${orders.filter(o=>o.risk===r).length} orders</strong></div>`).join('')}</div></section><section class="panel"><div class="panelhead"><h2>Recent activity</h2></div><div class="panelbody" style="padding-top:5px">${latest()}</div></section></div></div>`;}
function filterlist(recovery=false){return orders.filter(o=>(!recovery||['Attempt unsuccessful','Under review','Return in progress','Returned'].includes(o.status))&&(state.risk==='All'||o.risk===state.risk)&&(state.status==='All'||o.status===state.status)&&(o.id+' '+o.buyer+' '+o.item).toLowerCase().includes(state.query.toLowerCase()));}
function orderworkspace(recovery=false){return heading(recovery?'Recovery queue':'Order workspace',recovery?'Verify what happened. Find the next permitted step.':'Review readiness, delivery evidence and action history.',`<button class="btn" data-act="export">${icon('download')}Export orders</button>`)+`<section class="panel"><div class="filters"><label class="search">${icon('search')}<input aria-label="Search orders" id="search" value="${esc(state.query)}" placeholder="Search order, buyer or item"></label><select aria-label="Filter by risk" id="riskfilter">${['All','High','Medium','Low','Unscored'].map(v=>`<option ${state.risk===v?'selected':''} value="${v}">${v==='All'?'All risk levels':v+' risk'}</option>`).join('')}</select><select aria-label="Filter by status" id="statusfilter">${['All','Ready for dispatch','Out for delivery','Attempt unsuccessful','Under review','Delivered','Return in progress','Returned'].map(v=>`<option ${state.status===v?'selected':''}>${v}</option>`).join('')}</select></div><div id="orderresults">${table(filterlist(recovery))}</div></section><p class="footnote">${recovery?'First-attempt failures remain eligible for support. Final returns are tracked separately.':'Risk percentages and history are synthetic examples. Thresholds require pilot validation.'}</p>`;}
function timeline(o){return o.events.map(e=>`<div class="auditline"><div class="small">${esc(e.time)} · ${esc(e.actor)}</div><p>${esc(e.text)}</p></div>`).join('');}
function fact(l,v){return `<div class="fact"><span>${l}</span><strong>${esc(v)}</strong></div>`;}
function recommendation(o){if(o.status==='Delivered')return ['Delivery complete','Payment and handover are verified. No further outreach is needed.'];if(o.status==='Returned')return ['Return received','Track any remaining refund or seller claim to completion.'];if(o.status==='Return in progress')return ['Track the return','Keep the seller informed and complete the prepaid refund where applicable.'];if(o.status==='Under review')return ['Review the disputed attempt','Check location and contact evidence. Do not assign buyer fault before review.'];if(o.status==='Attempt unsuccessful')return ['Resolve the missed attempt','Ask the buyer what happened and offer a supported reattempt.'];if(o.readiness==='Confirmed ready')return ['Proceed with the delivery plan','Buyer readiness is confirmed. Confirmation is not a delivery guarantee.'];if(o.readiness==='Rescheduled')return ['Use the agreed delivery round','The supported slot is confirmed and visible to the buyer.'];if(o.risk==='Low'||o.risk==='Unscored')return ['Keep standard delivery','No additional readiness check is needed. Limited history is not high risk.'];return ['Check readiness before dispatch','Share the COD amount and expected day. Let the buyer confirm or report an issue.'];}
function detail(){const o=getOrder(),rec=recommendation(o);return `<button class="backlink" data-act="view" data-value="orders">${icon('back')} Back to orders</button>`+heading(o.id,`${o.buyer} · Bang Na hub · Original COD cohort`, `<button class="btn" data-act="role" data-value="buyer">${icon('user')}Buyer view</button>${badge(o.status)}`)+`<div class="detail-grid"><div class="stack"><section class="panel"><div class="panelhead"><h2>Order & delivery</h2>${badge(o.group+' group','blue')}</div><div class="panelbody"><div class="productline"><div class="packageicon">${icon('box')}</div><div><h3>${esc(o.item)}</h3><p class="small muted">${esc(o.shop)} · 1 item</p></div></div><div class="rule"></div><div class="facts">${fact('Order value',money(o.value))}${fact('Payment',o.payment)}${fact('Delivery slot',o.slot)}${fact('Buyer readiness',o.readiness)}${fact('Delivery address',o.address)}${fact('Contact',o.phone)}${fact('Delivery attempts',String(o.attempts))}${fact('Readiness messages',String(o.contactCount)+' / 2 per order')}</div></div></section><section class="panel"><div class="panelhead"><h2>Recommended next step</h2>${icon('shield')}</div><div class="panelbody"><h3>${rec[0]}</h3><p class="muted" style="font-size:14px;margin-top:7px">${rec[1]}</p><div class="actions">${!closed(o)?`<button class="btn primary" data-act="send" ${o.contactCount>=2||o.status==='Under review'||o.risk==='Low'||o.risk==='Unscored'?'disabled':''}>${icon('mail')}${o.contactCount?'Send follow-up':'Send readiness check'}</button><button class="btn" data-act="schedule">${icon('clock')}Arrange slot</button>`:''}${o.status==='Under review'?'<button class="btn primary" data-act="review">Review evidence</button>':''}${o.status==='Return in progress'?'<button class="btn" data-act="received">Confirm seller receipt</button>':''}${o.refund==='Refund processing'?'<button class="btn teal" data-act="refund">Complete demo refund</button>':''}${o.claim==='Submitted'?'<button class="btn" data-act="claimReview">Review seller claim</button>':''}</div><div class="note" style="margin-top:17px">${icon('shield')} No automatic hold for a risk score or unanswered message. Existing service commitments remain in place.</div></div></section>${o.pendingAddress?`<section class="panel"><div class="panelhead"><h2>Address change request</h2></div><div class="panelbody"><p>${esc(o.pendingAddress)}</p><div class="actions"><button class="btn primary" data-act="addressReview">Review request</button></div></div></section>`:''}${o.status==='Under review'?evidence(o):''}${['Return in progress','Returned'].includes(o.status)?returnpanel(o):''}<section class="panel"><div class="panelhead"><h2>Operational outcome</h2><span class="small muted">Demo controls</span></div><div class="panelbody"><p class="small muted">Simulate a verified courier event. Buyer tracking updates in the same session.</p><div class="actions"><button class="btn" data-act="dispatch" ${closed(o)||o.status==='Under review'||o.status==='Out for delivery'?'disabled':''}>${icon('truck')}Dispatch</button><button class="btn teal" data-act="delivered" ${closed(o)||o.status==='Under review'?'disabled':''}>${icon('check')}Confirm delivery</button><button class="btn" data-act="failed" ${closed(o)||o.status==='Under review'?'disabled':''}>Record failed attempt</button><button class="btn danger" data-act="return" ${closed(o)||o.status==='Under review'?'disabled':''}>Authorize return</button></div></div></section></div><div class="stack"><section class="panel"><div class="panelhead"><h2>AI risk assessment</h2>${badge(o.risk)}</div><div class="panelbody"><div class="riskhero"><div class="score ${o.risk.toLowerCase()}">${o.score===null?'—':o.score+'%'}</div><div><h3>Final failure risk</h3><p class="small muted">Illustrative baseline score<br>Assessed before intervention</p></div></div><div class="label">Associated factors</div><ul class="factors">${o.factors.map(f=>`<li>${esc(f)}</li>`).join('')}</ul><div class="rule"></div>${fact('Data quality',o.reliability)}<div class="note" style="margin-top:15px">Predicts delivery risk, not buyer intent. Pilot rules select actions; a future action model requires experimental evidence.</div></div></section><section class="panel"><div class="panelhead"><h2>Activity & audit trail</h2></div><div class="panelbody">${timeline(o)}</div></section></div></div>`;}
function evidence(o){return `<section class="panel"><div class="panelhead"><h2>Attempt evidence</h2>${badge('Review required','high')}</div><div class="panelbody"><div class="facts">${fact('Courier scan','25 Sep · 12:18')}${fact('Recorded reason','Recipient unavailable')}${fact('Location record','Scan 820 m from delivery address')}${fact('Contact record','No completed call recorded')}${fact('Buyer statement',o.statement||'I was available at the address.')}${fact('Decision','Pending human review')}</div><p class="note" style="margin-top:18px">These synthetic signals require joint review. GPS distance or a missing call alone does not prove misconduct.</p></div></section>`;}
function returnpanel(o){return `<section class="panel"><div class="panelhead"><h2>Return & seller support</h2>${badge(o.claim||'No open claim')}</div><div class="panelbody"><div class="facts">${fact('Return to seller',o.status==='Returned'?'Receipt confirmed':o.returnDate||'28 Sep 2026')}${fact('Buyer refund',o.refund||'Not applicable — unpaid COD')}${fact('Seller',o.shop)}${fact('Claim status',o.claim||'No claim submitted')}</div><div class="actions"><button class="btn" data-act="claim" ${o.claim?'disabled':''}>Open loss / damage claim</button></div></div></section>`;}
function pilot(){return heading('Pilot insights','Evaluate the original eligible cohort, including converted and cancelled orders.',`<button class="btn" data-act="export">${icon('download')}Export cohort</button>`)+`<div class="banner">${icon('chart')}<div><h3>Demonstration data only</h3><p>This sample shows measurement design. It does not establish AI effectiveness or statistical significance.</p></div></div><div class="pilotcols">${['Control','Rules','AI'].map((g,i)=>{const a=orders.filter(o=>o.group===g);return `<section class="panel experiment ${g==='AI'?'selected':''}"><div class="label">Arm 0${i+1}</div><h2>${g==='Control'?'Standard delivery':g==='Rules'?'Rule-based selection':'AI-based selection'}</h2><p>${g==='Control'?'Existing workflow without added readiness outreach.':g==='Rules'?'Simple verified-history rules choose outreach recipients.':'Risk predictions choose outreach recipients using comparable actions and budgets.'}</p><div class="num">${a.length}</div><p>Originally eligible orders</p><div class="rule"></div><div class="ministat"><span>Delivered</span><strong>${a.filter(o=>o.status==='Delivered').length}</strong></div><div class="ministat"><span>In return process</span><strong>${a.filter(o=>['Returned','Return in progress'].includes(o.status)).length}</strong></div><div class="ministat"><span>Readiness messages</span><strong>${a.reduce((s,o)=>s+o.contactCount,0)}</strong></div></section>`}).join('')}</div><div class="subgrid sectionspace"><section class="panel"><div class="panelhead"><h2>Scale-up gates</h2></div><div class="panelbody">${[['More completed deliveries','Measure delivered orders against the original eligible cohort.'],['Positive incremental net benefit','Deduct outreach, incentives, extra operations and allocated system costs.'],['Service quality protected','Check delays, complaints, cancellations and workload against pre-agreed limits.'],['AI adds value over rules','Use adequate sample size and comparable intervention budgets.']].map(([a,b])=>`<div class="policy"><h3>${a}</h3><p>${b}</p></div>`).join('')}</div></section><section class="panel"><div class="panelhead"><h2>Measurement notes</h2></div><div class="panelbody"><p class="muted" style="font-size:14px">Successful delivery creates an illustrative incremental benefit of ฿80 under the case assumptions: ฿60 commission plus ฿20 avoided reverse logistics.</p><div class="note" style="margin-top:18px">An early cancellation is a different outcome and does not recover GMV. Switching payment methods does not remove the order from its original COD cohort.</div><div class="rule"></div><p class="small muted">No achieved savings are displayed: this prototype has no real intervention-cost or control-outcome data.</p></div></section></div>`;}
function policies(){return heading('Service safeguards','Clear boundaries for a support-first pilot.')+`<div class="subgrid"><section class="panel"><div class="panelhead"><h2>Buyer protections</h2>${icon('shield')}</div><div class="panelbody">${[['No automatic restrictions','Risk scores and unanswered messages alone never hold a parcel or disable COD.'],['Limited history fallback','New buyers follow the standard delivery process unless there is a verified operational issue.'],['Voluntary changes','Buyer confirmation is required for payment changes and requested rescheduling.'],['Feasible delivery options','Offer only available rounds and pickup points that support the outstanding payment method.'],['Outreach limit','This prototype allows a maximum of two readiness messages per order. The pilot must validate the right frequency.']].map(([a,b])=>`<div class="policy"><h3>${a}</h3><p>${b}</p></div>`).join('')}</div></section><section class="panel"><div class="panelhead"><h2>Operational controls</h2>${icon('truck')}</div><div class="panelbody">${[['Evidence before attribution','Review disputed attempts before recording buyer fault.'],['Bounded reattempts','This demo allows up to two delivery attempts. A real pilot must align the limit with service policy and SLA.'],['Refunds after verification','A missed attempt alone does not trigger a refund while delivery remains planned.'],['Human approval','Disputes, return authorization and seller claims require an explicit review step.'],['Demo scope','All names, orders and scores are fictional. No real messages, payments, deliveries or refunds are processed. State resets on page reload.']].map(([a,b])=>`<div class="policy"><h3>${a}</h3><p>${b}</p></div>`).join('')}</div></section></div>`;}
function tracking(o){const returned=['Return in progress','Returned'].includes(o.status),del=o.status==='Delivered';const progress=del?4:o.status==='Out for delivery'||o.attempts>0?3:2;const title=del?'Delivered on 25 Sep':returned?(o.status==='Returned'?'Returned to seller':'Returning to seller'):o.status==='Under review'?'We’re checking your delivery':o.status==='Attempt unsuccessful'?'Let’s arrange another delivery':o.readiness==='Rescheduled'?'Your new delivery is arranged':'Expected '+o.slot.split(' · ')[0];return `<section class="mobilecard"><h3 class="tracking-title">${title}</h3><p class="small muted" style="margin-top:5px">${returned?'We’ll keep your return status updated.':del?'Your parcel has arrived. Thank you!':esc(o.slot)+(o.readiness==='Rescheduled'?' · Confirmed round':' · Estimated window')}</p><div class="trackline">${['Collected','Sorted','At hub','On the way','Delivered'].map((v,i)=>`${i?`<div class="trackconnector ${i<=progress?'done':''}"></div>`:''}<div class="tracknode ${i<progress?'done':i===progress?'current':''}">${i===progress?icon(del?'check':'box'):''}</div>`).join('')}</div><div class="tracklabels"><span>Collected</span><span>Sorted</span><span>At local hub</span><span>Out for delivery</span><span>Delivered</span></div></section>${buyerAction(o)}<section class="mobilecard"><div class="row" style="align-items:flex-start;color:var(--teal)">${icon('shield')}<div><h3 style="color:var(--ink)">Your delivery, your choice</h3><p class="small muted" style="margin-top:4px">Keep COD or choose a supported payment option. Only available delivery rounds are offered.</p></div></div></section><section class="mobilecard courier"><div class="avatar">KT</div><div class="text"><h3>Kai Thompson</h3><p class="small muted">SPX delivery partner</p></div><button class="iconbtn" aria-label="Message courier" data-act="courier">${icon('chat')}</button></section><section class="mobilecard"><div class="productline"><div class="packageicon">${icon('box')}</div><div style="flex:1;min-width:0"><h3>${esc(o.item)}</h3><p class="small muted">${esc(o.shop)} · ${money(o.value)}</p></div><button class="link" data-act="orderinfo">Details</button></div><div class="row between" style="margin-top:14px"><span class="small muted">${o.id}</span><button class="link" data-act="copy">Copy</button></div><div class="tracking-events">${o.events.map(e=>`<div class="trackevent"><time>${esc(e.time).replace(' · ','<br>')}</time><div class="eventtext">${esc(e.text)}</div></div>`).join('')}</div></section>${!closed(o)?`<section class="mobilecard"><h3>Delivery details</h3><p class="small muted" style="margin-top:8px">${esc(o.address)}</p><div class="row between" style="margin-top:12px"><span class="small">${esc(o.phone)}</span><button class="link" data-act="address">Edit details</button></div></section>`:''}`;}
function buyerAction(o){if(o.status==='Delivered')return `<section class="mobilecard"><div class="row between"><h3>Delivery complete</h3>${badge('Received','success')}</div><p class="muted" style="margin-top:8px">${o.payment==='COD collected'?money(o.value)+' collected on delivery.':'Payment confirmed.'}</p><button class="btn wide" style="margin-top:14px" data-act="proof">View delivery confirmation</button></section>`;
if(['Return in progress','Returned'].includes(o.status))return `<section class="mobilecard"><h3>${o.refund?'Your refund':'Your order return'}</h3><p class="muted" style="margin-top:7px">${o.refund?money(o.value)+' · '+esc(o.refund):'No payment was collected. No refund is due.'}</p><div class="notice">${o.status==='Returned'?'Seller receipt confirmed.':'Estimated return to seller: '+esc(o.returnDate||'28 Sep 2026')}</div><button class="btn wide" style="margin-top:13px" data-act="refundinfo">${o.refund?'View refund details':'View return details'}</button></section>`;
if(o.status==='Under review')return `<section class="mobilecard readiness"><div class="tag">Delivery review</div><h3>We’re checking what happened</h3><p class="muted" style="margin-top:7px">Your report is with our operations team. This attempt will not automatically count against your delivery history.</p><div class="notice">Case RV-${o.id.slice(-4)} · Awaiting review</div></section>`;
if(o.status==='Attempt unsuccessful')return `<section class="mobilecard readiness"><div class="tag">Delivery support</div><h3>Missed your delivery?</h3><p class="muted" style="margin-top:8px">The courier recorded: ${esc(o.reason||'Recipient unavailable')}. Tell us how we can help.</p><div class="mobileactions"><button class="btn primary" data-act="schedule">Choose another delivery round</button><button class="btn" data-act="dispute">I was available / report an issue</button>${o.payment==='COD'?'<button class="btn" data-act="pay">Explore digital payment</button>':''}</div></section>`;
if(o.readiness==='Cancellation requested')return `<section class="mobilecard readiness"><h3>Cancellation requested</h3><p class="muted" style="margin-top:8px">We’ll check whether the parcel can be intercepted. Your order is not cancelled until operations confirms.</p><div class="notice">Request sent to the delivery team</div></section>`;
if(o.readiness==='Confirmed ready'||o.readiness==='Rescheduled')return `<section class="mobilecard"><div class="row" style="color:var(--teal)">${icon('check')}<h3>${o.readiness==='Rescheduled'?'Delivery round updated':'You’re ready to receive'}</h3></div><p class="muted" style="margin-top:9px">${esc(o.slot)}<br>${o.payment==='COD'?'Please prepare '+money(o.value)+' for delivery.':'Payment confirmed. Nothing to pay on delivery.'}</p><div class="mobileactions two"><button class="btn" data-act="schedule">Change round</button><button class="btn" data-act="address">Edit details</button></div></section>`;
if(o.contactCount>0)return `<section class="mobilecard readiness"><div class="tag">A quick delivery check</div><h3>Will you be ready to receive?</h3><p class="muted" style="margin-top:7px">Your parcel is expected ${esc(o.slot)}. ${o.payment==='COD'?'Amount due: '+money(o.value)+'.':'Your payment is confirmed.'}</p><div class="mobileactions"><button class="btn primary" data-act="ready">${icon('check')}I’m ready to receive</button><button class="btn" data-act="schedule">Choose another round</button><div class="row between" style="margin:5px 0"><button class="link" data-act="address">Update details</button><button class="link" data-act="helporder">Other options</button></div></div><p class="small muted" style="margin-top:10px">No reply? Your delivery will continue as planned.</p></section>`;
return `<section class="mobilecard"><div class="row between"><h3>${o.payment==='COD'?'Cash on delivery':'Payment confirmed'}</h3><strong>${money(o.value)}</strong></div><p class="small muted" style="margin-top:9px">${o.payment==='COD'?'Please have your payment ready when the courier arrives.':'No payment will be collected at your door.'}</p><div class="mobileactions two"><button class="btn" data-act="schedule">Change round</button><button class="btn" data-act="helporder">Delivery options</button></div></section>`;}
function buyerOrders(){return `<section class="mobilecard"><h3>My deliveries</h3><p class="small muted" style="margin-top:5px">Demo buyers shown for scenario exploration</p></section>${orders.map(o=>`<button class="mobilecard ordercard" data-act="buyeropen" data-id="${o.id}"><div class="row between"><span class="small muted">${esc(o.shop)}</span>${badge(o.status)}</div><div class="productline" style="margin-top:15px"><div class="packageicon">${icon('box')}</div><div style="flex:1"><h3>${esc(o.item)}</h3><p class="small muted">${esc(o.buyer)} · ${money(o.value)}</p></div>${icon('arrow')}</div></button>`).join('')}`;}
function messages(o){return `<section class="mobilecard"><h3>Delivery updates</h3><p class="small muted">Messages for order ${o.id.slice(-6)}</p></section>${o.messages.length?o.messages.slice().reverse().map(m=>`<section class="message"><div class="row">${icon('mail')}<strong>Shopee Delivery</strong></div><p>${esc(m.text)}</p><time>${esc(m.time)}</time><div style="margin-top:12px"><button class="link" data-act="buyertab" data-value="tracking">View delivery</button></div></section>`).join(''):`<section class="mobilecard"><p class="muted">No readiness messages yet. Your standard tracking updates are available on the delivery page.</p><button class="btn wide" style="margin-top:15px" data-act="buyertab" data-value="tracking">View tracking</button></section>`}`;}
function support(o){return `<section class="mobilecard"><h3>How can we help?</h3><p class="small muted" style="margin-top:6px">Order ${o.id}</p><div class="mobileactions"><button class="btn" data-act="schedule" ${closed(o)?'disabled':''}>${icon('clock')}Change delivery round</button><button class="btn" data-act="address" ${closed(o)?'disabled':''}>${icon('pin')}Correct delivery details</button><button class="btn" data-act="dispute" ${closed(o)?'disabled':''}>${icon('shield')}Report a delivery issue</button><button class="btn" data-act="refundinfo">${icon('wallet')}Payment & refund status</button></div></section><section class="mobilecard"><h3>Your choices are protected</h3><p class="muted" style="margin-top:8px">An unanswered message will not automatically hold or cancel your order. You can keep cash on delivery.</p><p class="small muted" style="margin-top:12px">This is a concept prototype with synthetic orders. No real payment or support request is submitted.</p></section>`;}
function buyer(){const o=getOrder();return `<div class="buyer-layout"><div class="buyer-intro"><div class="label">Buyer experience</div><h1>A little clarity.<br>A smoother delivery.</h1><p>Follow the parcel, confirm readiness and get help when plans change.</p><div class="scenario"><label for="scenario">Explore a demo order</label><select id="scenario">${orders.map(x=>`<option value="${x.id}" ${x.id===o.id?'selected':''}>${x.buyer} · ${x.status}</option>`).join('')}</select><p class="small">Fictional buyers. Changes sync with the Operations view in this tab.</p></div><div class="demoaction"><div class="label" style="margin-bottom:12px">Demonstration controls</div><button class="btn wide" data-act="role" data-value="ops">${icon('grid')}Inspect this order in Operations</button>${!closed(o)&&o.contactCount===0&&!['Low','Unscored'].includes(o.risk)?'<button class="btn wide" style="margin-top:9px" data-act="send">Simulate a readiness message</button>':''}<p class="small muted" style="margin-top:12px">No real messages or payments. Refreshing the page resets the session.</p></div></div><div class="phone"><div class="statusbar"><span>15:55</span><div class="row"><span style="font-size:12px">▂▄▆</span><span>Wi-Fi</span><span style="color:var(--teal)">▰</span></div></div><div class="phonehead"><button class="iconbtn" aria-label="Back to orders" data-act="buyertab" data-value="orders">${icon('back')}</button><h2>${state.buyerTab==='orders'?'My Purchases':state.buyerTab==='messages'?'Messages':state.buyerTab==='support'?'Delivery Help':o.status==='Delivered'?'Delivered':'Delivery Details'}</h2><button class="iconbtn" aria-label="Delivery help" data-act="buyertab" data-value="support">${icon('help')}</button></div><div class="phonebody">${state.buyerTab==='orders'?buyerOrders():state.buyerTab==='messages'?messages(o):state.buyerTab==='support'?support(o):tracking(o)}</div><nav class="bottomnav" aria-label="Buyer navigation">${[['orders','box','Orders'],['tracking','truck','Tracking'],['messages','mail','Messages'],['support','help','Help']].map(([v,i,t])=>`<button class="${state.buyerTab===v?'active':''}" data-act="buyertab" data-value="${v}">${icon(i)}${t}</button>`).join('')}</nav></div></div>`;}
function render(){document.getElementById('app').innerHTML=renderAppHeader()+(state.role==='buyer'?buyer():`<div class="shell">${sidebar()}<main class="main">${state.view==='overview'?overview():state.view==='orders'?orderworkspace():state.view==='recovery'?orderworkspace(true):state.view==='detail'?detail():state.view==='pilot'?pilot():policies()}<div class="footnote">Shopee Delivery Success Engine · Case concept · Synthetic data · Not an official Shopee service</div></main></div>`);}
let modalKind='',returnFocus=null;
function modal(title,body,kind,submit='Confirm',danger=false){modalKind=kind;returnFocus=document.activeElement;const d=document.getElementById('modal');d.innerHTML=`<form id="modalform"><div class="modalhead"><h2>${title}</h2><button type="button" class="iconbtn" aria-label="Close dialog" data-act="close">${icon('close')}</button></div><div class="modalbody">${body}<div class="formerror" id="formerror" role="alert"></div></div><div class="modalfoot"><button type="button" class="btn" data-act="close">${kind==='info'?'Close':'Back'}</button>${kind==='info'?'':`<button type="submit" class="btn ${danger?'danger':'primary'}">${submit}</button>`}</div></form>`;d.showModal();}
function closeModal(){document.getElementById('modal').close();if(returnFocus?.isConnected)returnFocus.focus();}
function options(name,choices,selected){return choices.map(([v,a,b])=>`<label class="radiochoice"><input type="radio" name="${name}" value="${esc(v)}" ${v===selected?'checked':''} required><div><span>${a}</span>${b?`<span class="small">${b}</span>`:''}</div></label>`).join('');}
function schedule(){const o=getOrder();if(o.attempts>=2)return toast('Demo attempt limit reached. Operations must review the final outcome.');if(closed(o)||o.status==='Under review')return toast('This order cannot be rescheduled until its current case is resolved.');if(o.status==='Out for delivery')return modal('Change request after dispatch',`<p>Your parcel is already with the courier. A new round needs an operations check before it can be confirmed.</p><p>Use delivery help to report your availability. The current round remains in place.</p>`,'info');modal('Choose a delivery round',`<p>Only rounds supported by this hub are shown. Selecting one updates both the buyer and operations views.</p>${options('slot',[['26 Sep · 09:00–12:00','Tomorrow, 26 September','09:00–12:00 · 4 demo places available'],['26 Sep · 12:00–15:00','Tomorrow, 26 September','12:00–15:00 · 6 demo places available'],['27 Sep · 09:00–12:00','Sunday, 27 September','09:00–12:00 · 3 demo places available']])}<div class="note">Evening rounds and COD pickup points are not available for this demo hub.</div>`,'schedule','Confirm round');}
function action(act,el){const o=getOrder();switch(act){
case 'role':state.role=el.dataset.value;if(state.role==='ops')state.view='detail';state.buyerTab='tracking';render();break;
case 'view':state.view=el.dataset.value;state.query='';state.risk='All';state.status='All';render();break;
case 'open':state.selected=el.dataset.id;state.view='detail';render();break;
case 'buyeropen':state.selected=el.dataset.id;state.buyerTab='tracking';render();break;
case 'buyertab':state.buyerTab=el.dataset.value;render();break;
case 'clearfilters':state.query='';state.risk='All';state.status='All';render();break;
case 'close':closeModal();break;
case 'reset':modal('Reset the demo?',`<p>This clears changes made in this tab and restores all eight sample orders.</p>`,'reset','Reset demo',true);break;
case 'send':if(closed(o)||['Low','Unscored'].includes(o.risk)||o.status==='Under review'||o.contactCount>=2)return toast('No further readiness message is available for this order.');modal(o.contactCount?'Send a follow-up':'Send readiness check',`<p>This is a simulated in-app message. No real customer is contacted.</p><div class="note">Your ${esc(o.item.toLowerCase())} is expected ${esc(o.slot)}. ${o.payment==='COD'?'Please prepare '+money(o.value)+'.':''} Are you ready to receive it? You can confirm, choose an available round, or update your details.</div><p class="small" style="margin-top:15px">If the buyer does not respond, the current delivery plan stays in place.</p>`,'send','Send demo message');break;
case 'ready':if(closed(o))return; o.readiness='Confirmed ready';addEvent(o,'Buyer confirmed readiness; existing delivery plan retained','Buyer');render();toast('Readiness confirmed. Operations has been updated.');break;
case 'schedule':schedule();break;
case 'address':if(closed(o))return;modal('Update delivery details',`<p>Demo address edits are limited to the same Bangkok service area. Changes after dispatch require review.</p><div class="field"><label for="address">Delivery address</label><textarea id="address" name="address" required maxlength="240">${esc(o.address)}</textarea></div><div class="field"><label for="phone">Phone number</label><input id="phone" name="phone" required value="${esc(o.phone)}" type="tel" maxlength="25"></div>`,'address','Submit details');break;
case 'helporder':modal('Delivery options',`<p>Choose the help you need for this order.</p><div class="mobileactions">${o.payment==='COD'?'<button type="button" class="btn" data-act="pay">Explore optional digital payment</button>':''}<button type="button" class="btn" data-act="schedule">Change delivery round</button><button type="button" class="btn" data-act="cancelrequest">I no longer want this item</button></div><div class="note" style="margin-top:15px">You can keep COD. A cancellation request needs an operational check.</div>`,'info');break;
case 'addressReview':modal('Review address change',`<p>Confirm this correction is within the supported service area and the courier can apply it safely.</p><div class="note">${esc(o.pendingAddress)}</div>${options('decision',[['approve','Approve correction','Update the courier instructions and notify the buyer.'],['decline','Keep current address','Record why the change cannot be applied.']])}<div class="field"><label for="notes">Review notes</label><textarea id="notes" name="notes" required></textarea></div>`,'addressReview','Save decision');break;
case 'pay':if(document.getElementById('modal').open)closeModal();if(closed(o)||o.payment!=='COD')return toast('No outstanding COD conversion is available.');modal('Optional digital payment',`<p>Demo payment only. No banking credentials or real money are required.</p><div class="row between" style="margin-bottom:20px"><span>Order total</span><h2>${money(o.value)}</h2></div>${options('method',[['ShopeePay','ShopeePay','Simulated wallet payment'],['PromptPay','PromptPay','Simulated bank payment']],'ShopeePay')}<div class="note">After successful payment, the amount due at delivery becomes ฿0. Refunds follow the verified order status and applicable conditions.</div>`,'pay','Simulate payment');break;
case 'cancelrequest':if(document.getElementById('modal').open)closeModal();modal('Request cancellation',`<p>We will check whether this parcel can still be intercepted. Submitting this request does not immediately cancel the order.</p><div class="field"><label for="reason">Reason</label><select name="reason" id="reason"><option>No longer need the item</option>Ordered by mistake</option>Delivery took too long</option></select></div>`,'cancelrequest','Submit request',true);break;
case 'dispatch':if(closed(o)||o.status==='Under review')return; o.status='Out for delivery';addEvent(o,'Parcel dispatched on the confirmed delivery round','SPX Operations');render();toast('Dispatch recorded. Buyer tracking updated.');break;
case 'delivered':modal('Confirm successful delivery',`<p>Simulate a verified handover for ${esc(o.id)}.</p><div class="note">${o.payment==='COD'?'This also confirms collection of '+money(o.value)+' from the recipient.':'Prepaid order: nothing is collected on delivery.'}</div><label class="radiochoice" style="margin-top:16px"><input type="checkbox" name="verified" required><span>Handover ${o.payment==='COD'?'and payment collection are':'is'} verified</span></label>`,'delivered','Confirm delivery');break;
case 'failed':if(o.attempts>=2)return toast('Demo attempt limit reached. Review the order before authorizing return.');modal('Record unsuccessful attempt',`<p>This records an attempt, not a final failed delivery. The parcel may still be eligible for recovery.</p><div class="field"><label for="reason">Observed reason</label><select id="reason" name="reason"><option>Buyer unavailable</option><option>Unable to contact buyer</option><option>Cash unavailable</option><option>Address requires correction</option><option>Buyer refused delivery</option></select></div><div class="field"><label for="notes">Attempt evidence</label><textarea id="notes" name="notes" required placeholder="Record contact attempt, location check or buyer statement"></textarea></div>`,'failed','Record attempt');break;
case 'dispute':modal('Report a delivery issue',`<p>Our operations team will review your report before assigning buyer fault.</p><div class="field"><label for="statement">What happened?</label><textarea id="statement" name="statement" required placeholder="For example: I was at home, but no courier arrived."></textarea></div>`,'dispute','Submit report');break;
case 'review':modal('Review disputed attempt',`<p>Review location, contact records and the buyer statement together. This decision is simulated.</p>${options('decision',[['courier','Attempt not verified','Exclude this event from buyer-refusal history; arrange a new round.'],['valid','Attempt verified','Keep recovery available under service policy.'],['pending','More evidence needed','Keep the case open without assigning buyer fault.']])}<div class="field" style="margin-top:16px"><label for="notes">Review notes</label><textarea id="notes" name="notes" required placeholder="Explain the evidence and decision"></textarea></div>`,'review','Save review');break;
case 'return':modal('Authorize a final return',`<p>This is a human-reviewed final outcome. A risk score or silence alone is not a valid reason.</p>${options('reason',[['buyer','Verified buyer cancellation','Buyer explicitly requested cancellation.'],['policy','Permitted delivery attempts exhausted','The two-attempt demo limit and service obligations have been reviewed.'],['address','Address cannot be resolved','Documented attempts to resolve the address were unsuccessful.']])}<div class="field"><label for="notes">Authorization notes</label><textarea id="notes" name="notes" required placeholder="Document the verified reason and policy checks"></textarea></div><label class="radiochoice"><input type="checkbox" name="verified" required><span>I verified the final return conditions</span></label>`,'return','Authorize return',true);break;
case 'received':modal('Confirm seller receipt',`<p>Confirm that the returned parcel reached ${esc(o.shop)}. Any loss or damage claim remains a separate process.</p><label class="radiochoice"><input type="checkbox" name="verified" required><span>Seller receipt is verified</span></label>`,'received','Confirm receipt');break;
case 'refund':modal('Complete demo refund',`<p>Simulate a confirmed refund of ${money(o.value)} to the original payment method.</p><div class="note">A real system would wait for payment-provider confirmation before showing completion.</div>`,'refund','Confirm demo refund');break;
case 'claim':modal('Seller loss / damage claim',`<p>Order and return details are attached automatically. This demonstration does not upload files or submit a real claim.</p><div class="field"><label for="type">Claim type</label><select id="type" name="type"><option>Item damaged during return</option><option>Parcel missing during return</option></select></div><div class="field"><label for="notes">Evidence summary</label><textarea id="notes" name="notes" required placeholder="Describe the parcel condition or missing return"></textarea></div>`,'claim','Submit demo claim');break;
case 'claimReview':modal('Review seller claim',`<p>Claim ${'CL-'+o.id.slice(-4)} is linked to the order and return history.</p>${options('decision',[['Approved','Approve compensation','Eligibility and evidence have been reviewed.'],['More evidence requested','Request more evidence','Keep the claim open.']])}<div class="field"><label for="notes">Review notes</label><textarea id="notes" name="notes" required></textarea></div>`,'claimReview','Save decision');break;
case 'refundinfo':modal('Payment & return details',`<div class="facts">${fact('Order',o.id)}${fact('Payment',o.payment)}${fact('Refund status',o.refund||'No refund initiated')}${fact('Refund amount',o.refund?money(o.value):'Not applicable')}${fact('Return status',['Return in progress','Returned'].includes(o.status)?o.status:'No final return')}${fact('Expected seller receipt',o.returnDate||'Not applicable')}</div><div class="note" style="margin-top:20px">An unsuccessful attempt does not trigger an automatic refund while delivery remains planned. This is a simulated status, not a real transaction.</div>`,'info');break;
case 'orderinfo':modal('Order details',`<div class="facts">${fact('Order',o.id)}${fact('Item',o.item)}${fact('Seller',o.shop)}${fact('Quantity','1')}${fact('Total',money(o.value))}${fact('Payment',o.payment)}${fact('Buyer',o.buyer)}${fact('Address',o.address)}</div>`,'info');break;
case 'proof':modal('Delivery confirmation',`<div class="facts">${fact('Status','Handover verified')}${fact('Recipient',o.buyer)}${fact('Delivery partner','SPX Express')}${fact('Payment',o.payment)}</div><div class="note" style="margin-top:18px">Synthetic confirmation record. No real delivery photo or signature is collected in this prototype.</div>`,'info');break;
case 'courier':modal('Message your courier',`<p>Send a delivery note in this demo. Do not share banking or verification codes.</p><div class="field"><label for="message">Your message</label><textarea id="message" name="message" required placeholder="For example: Please call when you reach the lobby."></textarea></div>`,'courier','Send demo note');break;
case 'copy':navigator.clipboard?.writeText(o.id).then(()=>toast('Tracking number copied.')).catch(()=>toast(o.id));break;
case 'export':exportOrders();break;
}}
function submitModal(e){e.preventDefault();const f=e.target;if(!f.checkValidity())return f.reportValidity();const d=new FormData(f),o=getOrder();const val=n=>String(d.get(n)||'').trim();const error=t=>document.getElementById('formerror').textContent=t;let msg='Updated successfully.';
switch(modalKind){case 'reset':orders=seeds();state={role:'ops',view:'overview',selected:orders[0].id,buyerTab:'tracking',query:'',risk:'All',status:'All'};msg='Demo restored to its initial state.';break;
case 'send':if(o.contactCount>=2)return error('The outreach limit has been reached.');o.contactCount++;o.readiness='Awaiting response';o.messages.push({time:'25 Sep · Just now',text:`Your ${o.item.toLowerCase()} is expected ${o.slot}. ${o.payment==='COD'?'COD amount: '+money(o.value)+'. ':''}Please confirm readiness or tell us what needs to change. No reply will not hold your delivery.`});addEvent(o,o.contactCount===1?'Readiness check sent; standard delivery remains scheduled':'One follow-up sent; outreach limit reached','Operations');msg='Demo message sent. Open Buyer app to respond.';break;
case 'schedule':if(!val('slot'))return error('Choose a delivery round.');o.slot=val('slot');o.readiness='Rescheduled';if(o.status==='Attempt unsuccessful')o.status='Ready for dispatch';addEvent(o,'Supported delivery round confirmed: '+o.slot);o.messages.push({time:'25 Sep · Just now',text:'Your delivery round is confirmed for '+o.slot+'.'});msg='Delivery round confirmed in both views.';break;
case 'address':if(val('address').length<12)return error('Please enter a complete delivery address.');if(val('phone').replace(/\D/g,'').length<9)return error('Please enter a valid phone number.');if(o.status==='Out for delivery'){o.pendingAddress=val('address');o.pendingPhone=val('phone');addEvent(o,'Address change requested after dispatch; operations must verify: '+val('address'));msg='Change submitted for review. The current address is unchanged.';}else{o.address=val('address');o.phone=val('phone');addEvent(o,'Buyer contact details updated within the demo service area');msg='Delivery details updated.';}break;
case 'addressReview':if(!val('notes'))return error('Add review notes.');if(val('decision')==='approve'){o.address=o.pendingAddress;o.phone=o.pendingPhone;}addEvent(o,'Address correction '+(val('decision')==='approve'?'approved':'declined')+': '+val('notes'),'Human review');delete o.pendingAddress;delete o.pendingPhone;msg='Address review completed.';break;
case 'pay':o.payment='Prepaid';addEvent(o,'Demo '+val('method')+' payment confirmed; COD amount set to zero','Payment simulation');msg='Demo payment confirmed. Amount due at delivery: ฿0.';break;
case 'cancelrequest':o.readiness='Cancellation requested';addEvent(o,'Buyer requested cancellation: '+val('reason')+'. Interception pending review.','Buyer');msg='Request submitted. Operations must confirm interception.';break;
case 'delivered':if(closed(o)||o.status==='Under review')return error('This order is not available for delivery confirmation.');o.status='Delivered';o.attempts++;if(o.payment==='COD')o.payment='COD collected';addEvent(o,'Parcel delivered; handover and payment verified','SPX Operations');msg='Delivery recorded. Buyer tracking updated.';break;
case 'failed':if(!val('notes'))return error('Add attempt evidence.');if(closed(o))return error('This order is already closed.');o.status='Attempt unsuccessful';o.reason=val('reason');o.attempts++;o.readiness='Recovery needed';addEvent(o,'Attempt unsuccessful: '+o.reason+'. Evidence: '+val('notes'),'Courier record');msg='Attempt recorded. Recovery options are available.';break;
case 'dispute':if(!val('statement'))return error('Please describe the issue.');o.status='Under review';o.readiness='Disputed attempt';o.statement=val('statement');addEvent(o,'Buyer report: '+val('statement')+'. No automatic buyer-fault attribution.','Buyer');msg='Report submitted for human review.';break;
case 'review':if(!val('notes'))return error('Add review notes.');if(val('decision')==='pending'){addEvent(o,'Additional evidence requested: '+val('notes'),'Human review');}else{o.status='Attempt unsuccessful';o.readiness='Recovery needed';o.reason=val('decision')==='courier'?'Attempt not verified':'Verified unsuccessful attempt';o.reliability='Human review completed';addEvent(o,(val('decision')==='courier'?'Attempt excluded from buyer-refusal history. ':'Attempt verified; recovery remains available. ')+val('notes'),'Human review');}msg='Review saved to the audit trail.';break;
case 'return':if(!val('notes'))return error('Provide authorization notes.');if(val('reason')==='policy'&&o.attempts<2)return error('The two-attempt demo limit has not been reached.');if(val('reason')==='buyer'&&o.readiness!=='Cancellation requested')return error('No explicit buyer cancellation request is recorded. Select an evidenced reason or obtain the request first.');o.status='Return in progress';o.returnDate='28 Sep 2026';if(o.payment==='Prepaid')o.refund='Refund processing';addEvent(o,'Final return authorized: '+val('reason')+'. '+val('notes'),'Human review');msg='Return authorized. Buyer and seller tracking updated.';break;
case 'received':o.status='Returned';addEvent(o,'Returned parcel received by seller','Seller receipt');msg='Seller receipt confirmed.';break;
case 'refund':o.refund='Refund completed';addEvent(o,'Demo refund of '+money(o.value)+' confirmed to original payment method','Payment simulation');msg='Demo refund completed.';break;
case 'claim':if(!val('notes'))return error('Describe the evidence.');o.claim='Submitted';addEvent(o,'Seller claim submitted: '+val('type')+'. '+val('notes'),'Seller support');msg='Claim submitted with order and return records attached.';break;
case 'claimReview':if(!val('notes'))return error('Add review notes.');o.claim=val('decision');addEvent(o,'Seller claim '+o.claim.toLowerCase()+': '+val('notes'),'Claims review');msg='Claim decision saved.';break;
case 'courier':if(!val('message'))return error('Enter a message.');addEvent(o,'Buyer delivery note: '+val('message'),'Buyer');msg='Demo note added to this order. No real message sent.';break;
}closeModal();render();toast(msg);}
function exportOrders(){const cols=['Order ID','Buyer','Original cohort','Experiment group','Risk','Status','Readiness','Payment','Value THB','Attempts','Messages','Refund','Claim'];const rows=orders.map(o=>[o.id,o.buyer,'COD',o.group,o.risk,o.status,o.readiness,o.payment,o.value,o.attempts,o.contactCount,o.refund||'',o.claim||'']);const safe=v=>'"'+String(v).replace(/"/g,'""')+'"';const csv=[cols,...rows].map(r=>r.map(safe).join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='delivery-demo-cohort.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Synthetic cohort exported.');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(b&&!b.disabled){if(document.getElementById('modal').open&&['schedule'].includes(b.dataset.act))closeModal();action(b.dataset.act,b);}});
document.addEventListener('change',e=>{if(e.target.id==='scenario'){state.selected=e.target.value;state.buyerTab='tracking';render();}if(e.target.id==='riskfilter'||e.target.id==='statusfilter'){state[e.target.id==='riskfilter'?'risk':'status']=e.target.value;document.getElementById('orderresults').innerHTML=table(filterlist(state.view==='recovery'));}});
document.addEventListener('input',e=>{if(e.target.id==='search'){state.query=e.target.value;document.getElementById('orderresults').innerHTML=table(filterlist(state.view==='recovery'));}});
document.addEventListener('submit',e=>{if(e.target.id==='modalform')submitModal(e);});
document.getElementById('modal').addEventListener('click',e=>{if(e.target===document.getElementById('modal'))closeModal();});
render();
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'list_demo_orders',title:'List demo delivery orders',description:'Read synthetic order states in this prototype. Does not contact buyers or modify orders.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:async()=>orders.map(o=>({id:o.id,status:o.status,readiness:o.readiness,risk:o.risk,payment:o.payment}))});document.modelContext.registerTool({name:'open_demo_order',title:'Open a demo order',description:'Navigate to an existing synthetic order in buyer or operations view. Does not change the order.',inputSchema:{type:'object',properties:{orderId:{type:'string'},view:{type:'string',enum:['buyer','ops']}},required:['orderId','view'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||!orders.some(o=>o.id===input.orderId)||!['buyer','ops'].includes(input.view))throw new Error('Valid demo orderId and buyer or ops view required.');state.selected=input.orderId;state.role=input.view;state.view='detail';state.buyerTab='tracking';render();return{opened:state.selected,view:state.role};}});}catch(e){console.warn('Optional agent navigation unavailable');}}

})();
